function [t] = motor_line(tm, om, ts, wn)
%MOTOR_LINE  The torque [N m] the motor gives for the driver's demand tm at speed om [rad/s]: the demand inside the torque-speed
%   line of stall torque ts and no-load speed wn.
%   tm: real[1] (passed a plain number)
%   om: real[1] (passed a plain number)
%   ts: real[1] (passed a plain number)
%   wn: real[1] (passed a plain number)
%   returns t: real[1] (passed a plain number)
%   Generated by tools/pcode.py from the pseudocode (trinetra-pcode/2); do not edit.
    t = 0;
    lo0 = ((-(ts)) * (1 + (om / wn)));
    hi0 = (ts * (1 - (om / wn)));
    if (lo0 < 0)
        h__26 = lo0;
    else
        h__26 = 0;
    end
    lo = h__26;
    if (hi0 > 0)
        h__27 = hi0;
    else
        h__27 = 0;
    end
    hi = h__27;
    t = asils.models.coilsat.act_clamp(tm, lo, hi);
end
